function coverageFinancials(){if(R.financials)return financials();let years=Q.kpi?.years||{},rows=Object.keys(years).map(fy=>{let x=years[fy]||{};return[E(fy),x.revenue_lakhs==null?'—':N(x.revenue_lakhs/100,1),x.ebitda_lakhs==null?'—':N(x.ebitda_lakhs/100,1),x.ebitda_margin_pct==null?'—':N(x.ebitda_margin_pct,1)+'%',x.pat_lakhs==null?'—':N(x.pat_lakhs/100,1),x.roce_pct==null?'—':N(x.roce_pct,1)+'%']});return'<div class="stack">'+card('Reported operating record',badge('Reported fact')+table(['Year','Revenue ₹cr','EBITDA ₹cr','Margin','PAT ₹cr','RoCE'],rows))+creditRatingCard()+'</div>'}
